-- Recovered verbatim from the production Supabase migration ledger for L0 replay parity.
create table if not exists public.hq_workforce_skill_promotions(id uuid primary key default gen_random_uuid(),promotion_key text not null unique,learning_candidate_id uuid not null references public.hq_workforce_learning_candidates(id),skill_key text not null,from_version integer not null,to_version integer not null,proposed_skill_id uuid references public.hq_workforce_skills(id),status text not null check(status in ('candidate','benchmarking','failed','probation','promoted','rolled_back')),benchmark_passed boolean,benchmark_evidence jsonb not null default '{}'::jsonb,probation_evidence jsonb not null default '{}'::jsonb,rollback_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table public.hq_workforce_skill_promotions enable row level security;
create or replace function public.hq_workforce_prepare_skill_promotion(p_candidate_id uuid,p_skill_key text) returns uuid language plpgsql security invoker set search_path=public as $$ declare c public.hq_workforce_learning_candidates%rowtype; s public.hq_workforce_skills%rowtype; new_id uuid; pid uuid; begin select * into c from public.hq_workforce_learning_candidates where id=p_candidate_id; if not found or c.status<>'approved' then raise exception 'Approved learning candidate required'; end if; select * into s from public.hq_workforce_skills where skill_key=p_skill_key and status='certified' order by version desc limit 1; if not found then raise exception 'Certified source skill required'; end if; insert into public.hq_workforce_skills(skill_key,version,title,lane_key,execution_method,required_context,required_competencies,procedure,verification,recovery,status) values(s.skill_key,s.version+1,s.title,s.lane_key,s.execution_method,s.required_context,s.required_competencies,s.procedure || jsonb_build_object('learning_candidate_id',c.id,'learning_statement',c.statement),s.verification,s.recovery,'draft') returning id into new_id; insert into public.hq_workforce_skill_promotions(promotion_key,learning_candidate_id,skill_key,from_version,to_version,proposed_skill_id,status) values('promotion-'||p_skill_key||'-v'||s.version||'-v'||(s.version+1)||'-'||substr(c.id::text,1,8),c.id,p_skill_key,s.version,s.version+1,new_id,'candidate') returning id into pid; return pid; end $$;
create or replace function public.hq_workforce_record_skill_benchmark(p_promotion_id uuid,p_passed boolean,p_evidence jsonb) returns text language plpgsql security invoker set search_path=public as $$ declare p public.hq_workforce_skill_promotions%rowtype; begin select * into p from public.hq_workforce_skill_promotions where id=p_promotion_id for update; if not found or p.status not in ('candidate','benchmarking') then raise exception 'Promotion not benchmarkable'; end if; if p_passed then update public.hq_workforce_skill_promotions set status='probation',benchmark_passed=true,benchmark_evidence=coalesce(p_evidence,'{}'),updated_at=now() where id=p_promotion_id; update public.hq_workforce_skills set status='probation' where id=p.proposed_skill_id; return 'probation'; else update public.hq_workforce_skill_promotions set status='failed',benchmark_passed=false,benchmark_evidence=coalesce(p_evidence,'{}'),updated_at=now() where id=p_promotion_id; update public.hq_workforce_skills set status='draft' where id=p.proposed_skill_id; return 'failed'; end if; end $$;
create or replace function public.hq_workforce_finalize_skill_probation(p_promotion_id uuid,p_execution_passed boolean,p_outcome_verified boolean,p_evidence jsonb) returns text language plpgsql security invoker set search_path=public as $$ declare p public.hq_workforce_skill_promotions%rowtype; begin select * into p from public.hq_workforce_skill_promotions where id=p_promotion_id for update; if not found or p.status<>'probation' then raise exception 'Promotion not in probation'; end if; if p_execution_passed and p_outcome_verified then update public.hq_workforce_skills set status='retired' where skill_key=p.skill_key and version=p.from_version and status='certified'; update public.hq_workforce_skills set status='certified' where id=p.proposed_skill_id; update public.hq_workforce_skill_promotions set status='promoted',probation_evidence=coalesce(p_evidence,'{}'),updated_at=now() where id=p_promotion_id; return 'promoted'; else update public.hq_workforce_skills set status='draft' where id=p.proposed_skill_id; update public.hq_workforce_skill_promotions set status='rolled_back',probation_evidence=coalesce(p_evidence,'{}'),rollback_reason='Probation execution or outcome verification failed',updated_at=now() where id=p_promotion_id; return 'rolled_back'; end if; end $$;
revoke all on table public.hq_workforce_skill_promotions from anon,authenticated; revoke all on function public.hq_workforce_prepare_skill_promotion(uuid,text) from public,anon,authenticated; revoke all on function public.hq_workforce_record_skill_benchmark(uuid,boolean,jsonb) from public,anon,authenticated; revoke all on function public.hq_workforce_finalize_skill_probation(uuid,boolean,boolean,jsonb) from public,anon,authenticated;
